import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1.6, 1, 1, 1);

  // Create material with TSL nodes
  const material = new MeshBasicNodeMaterial();

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position
  if (config.scenePosition) {
    mesh.position.set(
      config.scenePosition.x,
      config.scenePosition.y,
      config.scenePosition.z
    );
  }

  // Apply rotation
  if (config.scenePosition?.rotation) {
    mesh.rotation.order = 'XYZ';
    mesh.rotation.x = config.scenePosition.rotation.x || 0;
    mesh.rotation.y = config.scenePosition.rotation.y || 0;
    mesh.rotation.z = config.scenePosition.rotation.z || 0;
  }

  // Apply scale
  if (config.scenePosition?.scale) {
    mesh.scale.set(
      config.scenePosition.scale.x || 1,
      config.scenePosition.scale.y || 1,
      config.scenePosition.scale.z || 1
    );
  }

  // Load texture asynchronously and update material
  let texObj = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = 'srgb';
    texObj = tex;
    material.colorNode = texture(tex);
    material.needsUpdate = true;
  });

  // Setup userData for cleanup
  mesh.userData.handlers = {};
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texObj) {
      texObj.dispose();
    }
  };

  return mesh;
}
